{
["gossip"] = "Select _\"Hello, Frankal. I've heard that you might have some information as to the whereabouts of Mistress Natalia Mar'alith.\"_ ||gossip 116979",
["guide"] = "LEVELING\\Classic (11-60)\\Silithus (59-60)",
["event"] = "GOSSIP_MINED",
["locale"] = "enUS",
["step"] = 17,
["time"] = 1782092690,
